// @pit: {"label": "Docs for the nested-run guard, then npm run check"}
async ({ workspace: { read, edit }, shell: { execFile } }) => {
  const rep = async (file: string, a: string, b: string) => {
    const r = await read(file, { format: "raw" });
    if (!r.content.includes(a)) throw new Error(`${file} missing`);
    await edit(file, { revision: r.revision, changes: [{ kind: "replaceFile", content: r.content.replace(a, b) }] });
  };
  await rep("docs/security.md", "## What pi-action removes from text", `## A run inside a run

pi-action sets \`PI_ACTION_RUNNING\` (its process ID) in its own environment when it starts. All tools of the agent inherit it. When the variable is set, pi-action does not run: the step fails at once, before pi-action reads the inputs or changes a ref. The \`Save pi thread state\` step does not push either. Thus, the agent cannot start a second run of the action, for example with \`node src/index.ts\`. A second run would work on the same thread refs, and break the run that started it.

## What pi-action removes from text`);
  await rep("CONTRIBUTING.md", "| [`src/run.ts`](src/run.ts) | Orchestration of a run |\n", "| [`src/run.ts`](src/run.ts) | Orchestration of a run |\n| [`src/nested-run.ts`](src/nested-run.ts) | `PI_ACTION_RUNNING`: stops a run that the agent's tools start inside a run |\n");
  const chk = await execFile("npm", ["run", "check"], { maxLines: 8, truncate: "tail", timeoutMs: 290000 });
  return { code: chk.code, out: chk.stdout };
}
